const optionLabelsForVariants = `-- name: OptionLabelsForVariants :many
SELECT vov.variant_id, ov.value
FROM swag_variant_option_values vov
JOIN swag_option_values ov ON ov.id = vov.option_value_id
JOIN swag_product_options o ON o.id = ov.option_id
WHERE vov.variant_id IN (/*SLICE:variant_ids*/?)
ORDER BY vov.variant_id, o.sort, o.name
`

type OptionLabelsForVariantsRow struct {
	VariantID string
	Value     string
}

func (q *Queries) OptionLabelsForVariants(ctx context.Context, variantIds []string) ([]OptionLabelsForVariantsRow, error) {
	query := optionLabelsForVariants
	var queryParams []interface{}
	if len(variantIds) > 0 {
		for _, v := range variantIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:variant_ids*/?", strings.Repeat(",?", len(variantIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:variant_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OptionLabelsForVariantsRow
	for rows.Next() {
		var i OptionLabelsForVariantsRow
		if err := rows.Scan(&i.VariantID, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

